/** static void AnimGuillotinePincer(struct Sprite *sprite) */
export function AnimGuillotinePincer(sprite: any): any {
  let startXOffset: any = 32;
      let startYOffset: any = -32;
      let endXOffset: any = 16;
      let endYOffset: any = -16;
      if (gBattleAnimArgs[0])
      {
          startXOffset = -32;
          startYOffset = 32;
          endXOffset = -16;
          endYOffset = 16;
          StartSpriteAnim(sprite, gBattleAnimArgs[0]);
      }

      sprite.x += startXOffset;
      sprite.y += startYOffset;
      sprite.data[0] = 6;
      sprite.data[1] = sprite.x;
      sprite.data[2] = GetBattlerSpriteCoord(gBattleAnimTarget, BATTLER_COORD_X_2) + endXOffset;
      sprite.data[3] = sprite.y;
      sprite.data[4] = GetBattlerSpriteCoord(gBattleAnimTarget, BATTLER_COORD_Y_PIC_OFFSET) + endYOffset;
      InitAnimLinearTranslation(sprite);
      sprite.data[5] = gBattleAnimArgs[0];
      sprite.data[6] = sprite.data[0];
      sprite.callback = AnimGuillotinePincer_Step1;
}

/** static void AnimGuillotinePincer_Step1(struct Sprite *sprite) */
export function AnimGuillotinePincer_Step1(sprite: any): any {
  if (AnimTranslateLinear(sprite) && sprite.animEnded)
      {
          SeekSpriteAnim(sprite, 0);
          sprite.animPaused = 1;
          sprite.x += sprite.x2;
          sprite.y += sprite.y2;
          sprite.x2 = 2;
          sprite.y2 = -2;
          sprite.data[0] = sprite.data[6];
          sprite.data[1] ^= 1;
          sprite.data[2] ^= 1;
          sprite.data[4] = 0;
          sprite.data[3] = 0;
          sprite.callback = AnimGuillotinePincer_Step2;
      }
}

/** static void AnimGuillotinePincer_Step2(struct Sprite *sprite) */
export function AnimGuillotinePincer_Step2(sprite: any): any {
  if (sprite.data[3])
      {
          sprite.x2 = -sprite.x2;
          sprite.y2 = -sprite.y2;
      }

      sprite.data[3] ^= 1;
      if (++sprite.data[4] == 51)
      {
          sprite.y2 = 0;
          sprite.x2 = 0;
          sprite.data[4] = 0;
          sprite.data[3] = 0;
          sprite.animPaused = 0;
          StartSpriteAnim(sprite, sprite.data[5] ^ 1);
          sprite.callback = AnimGuillotinePincer_Step3;
      }
}

/** static void AnimGuillotinePincer_Step3(struct Sprite *sprite) */
export function AnimGuillotinePincer_Step3(sprite: any): any {
  if (AnimTranslateLinear(sprite))
          DestroyAnimSprite(sprite);
}

