  sprite.x = GetBattlerSpriteCoord(gBattleAnimTarget, BATTLER_COORD_X) - 16;
      sprite.y = GetBattlerYCoordWithElevation(gBattleAnimTarget) + 16;
      sprite.data[0] = 0;
      sprite.data[1] = 0;
      sprite.data[2] = 0;
      sprite.data[3] = 16;
